import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.BSsJcWLc.js";const h=JSON.parse('{"title":"ML Training","description":"","frontmatter":{},"headers":[],"relativePath":"guides/ml-training.md","filePath":"guides/ml-training.md"}'),n={name:"guides/ml-training.md"};function s(i,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="ml-training" tabindex="-1">ML Training <a class="header-anchor" href="#ml-training" aria-label="Permalink to &quot;ML Training&quot;">​</a></h1><p>Train decoders for real-time BCI using the ML Workbench.</p><h2 id="data-sources" tabindex="-1">Data Sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data Sources&quot;">​</a></h2><p>The <strong>Data</strong> tab offers three sources:</p><h3 id="moabb-public-datasets" tabindex="-1">MOABB Public Datasets <a class="header-anchor" href="#moabb-public-datasets" aria-label="Permalink to &quot;MOABB Public Datasets&quot;">​</a></h3><p>Browse public BCI datasets from <a href="https://moabb.neurotechx.com" target="_blank" rel="noreferrer">MOABB</a>. Select a dataset, choose a subject, and click to load. Data downloads automatically on first use.</p><h3 id="internal-datasets" tabindex="-1">Internal Datasets <a class="header-anchor" href="#internal-datasets" aria-label="Permalink to &quot;Internal Datasets&quot;">​</a></h3><p>Import your own recordings via the Data Explorer (<strong>Data</strong> page → <strong>Datasets</strong> tab → <strong>Import</strong>). Supports <code>.fif</code>, <code>.h5</code>, and <code>.hdf5</code> files. After importing, datasets appear in the ML Workbench for loading.</p><h3 id="recordings" tabindex="-1">Recordings <a class="header-anchor" href="#recordings" aria-label="Permalink to &quot;Recordings&quot;">​</a></h3><p>Browse recordings in the <strong>Recordings</strong> tab. Select a recording and click <strong>Load</strong> to epoch with the configured preprocessing. Toggle event chips to select classes for training.</p><h2 id="preprocessing" tabindex="-1">Preprocessing <a class="header-anchor" href="#preprocessing" aria-label="Permalink to &quot;Preprocessing&quot;">​</a></h2><p>Before loading, configure:</p><ul><li><strong>Low/High Cut (Hz)</strong> — Bandpass filter bounds (e.g., 1–40 Hz for EEG, 20–200 Hz for EMG)</li><li><strong>Common Average Reference</strong> — Subtract mean across channels</li><li><strong>Epoch Window</strong> — <code>tmin</code> and <code>tmax</code> define the time window around each event (e.g., -0.2s to 0.8s)</li></ul><h2 id="event-selection" tabindex="-1">Event Selection <a class="header-anchor" href="#event-selection" aria-label="Permalink to &quot;Event Selection&quot;">​</a></h2><p>Toggle event chips to select which classes are used for training.</p><h2 id="training" tabindex="-1">Training <a class="header-anchor" href="#training" aria-label="Permalink to &quot;Training&quot;">​</a></h2><p>Switch to the <strong>Training</strong> tab:</p><ol><li><strong>Select a model</strong> — EEGNet, CSP+LDA, or any registered decoder type</li><li><strong>Configure hyperparameters</strong> — epochs, batch size, learning rate, validation split, early stopping</li><li><strong>Start Training</strong> — runs in background with live per-epoch progress</li></ol><h2 id="saving-decoders" tabindex="-1">Saving Decoders <a class="header-anchor" href="#saving-decoders" aria-label="Permalink to &quot;Saving Decoders&quot;">​</a></h2><p>Click <strong>Save Decoder</strong> on a completed job to save to <code>data/studies/&lt;study&gt;/decoders/</code>.</p><h2 id="output-format" tabindex="-1">Output Format <a class="header-anchor" href="#output-format" aria-label="Permalink to &quot;Output Format&quot;">​</a></h2><p>Decoders save as a JSON config + model file pair:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>decoder_name.json      # Config: model type, input shape, class mapping</span></span>
<span class="line"><span>decoder_name.pt        # Neural model weights (PyTorch state dict)</span></span>
<span class="line"><span>decoder_name.joblib    # Classical pipeline (CSP+LDA/SVM) — used instead of .pt</span></span></code></pre></div>`,23)])])}const u=a(n,[["render",s]]);export{h as __pageData,u as default};
